const input = $input.first()?.json?.body || $input.first()?.json || {};
const clamp = (value, min, max) => Math.min(max, Math.max(min, Number(value) || min));
const phases = Array.isArray(input.lessonPlan) ? input.lessonPlan : [];
const compactPhases = phases
  .filter((phase) => phase && phase.key !== 'cover')
  .map((phase) => ({
    key: String(phase.key || ''),
    title: String(phase.title || ''),
    steps: (Array.isArray(phase.steps) ? phase.steps : []).map((step, index) => ({
      id: String(step.id || `${phase.key || 'phase'}-step-${index + 1}`),
      title: String(step.title || ''),
      duration: String(step.duration || step.time || ''),
      objective: String(step.objective || ''),
      activity: String(step.activity || ''),
      flow: String(step.flow || step.activitySteps || ''),
      resources: String(step.resources || '')
    }))
  }));
const stepCount = compactPhases.reduce((sum, phase) => sum + phase.steps.length, 0);
if (!stepCount) throw new Error('lessonPlan must contain at least one lesson step');
const totalSlides = clamp(input.totalSlides || stepCount * 2, Math.max(2, stepCount + 1), 40);
const styleMap = {
  'blue-business': 'Whimsical sky adventure with paper-cut clouds, rainbow colors, rounded shapes, bright blue, yellow, coral, mint and lavender.',
  'red-business': 'Magical storybook forest with hand-painted leaves, flowers, friendly woodland details, warm cream, green, teal, peach and yellow.',
  'nature-business': 'Playful space adventure with soft clay planets, friendly stars, orbit lines, indigo, violet, turquoise, coral and yellow.'
};
return [{ json: {
  courseTitle: String(input.courseMeta?.courseTitle || input.courseMeta?.title || input.courseTitle || 'English Learning Adventure'),
  courseContext: JSON.stringify(input.courseMeta || {}),
  lessonPlan: JSON.stringify(compactPhases),
  templateId: String(input.templateId || 'blue-business'),
  visualStyle: styleMap[input.templateId] || styleMap['blue-business'],
  totalSlides,
  stepCount,
  slideWidth: 940,
  slideHeight: 529
} }];

const raw = $input.first()?.json || {};
const prepared = $('Prepare Course Context').first().json;
const phases = JSON.parse(prepared.lessonPlan);
const stepMap = new Map(phases.flatMap((phase) => phase.steps.map((step) => [step.id, { ...step, phaseKey: phase.key, phaseTitle: phase.title }])));
const stepIds = [...stepMap.keys()];
const cjk = /[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]/;

const stripCodeFence = (value) => String(value || '')
  .trim()
  .replace(/^\`{3}(?:json)?\s*/i, '')
  .replace(/\`{3}$/i, '')
  .trim();

const extractJsonObject = (value) => {
  const text = stripCodeFence(value);
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  return first >= 0 && last > first ? text.slice(first, last + 1) : text;
};

const parseJsonLike = (value) => {
  if (value && typeof value === 'object') return value;
  const extracted = extractJsonObject(value);
  try {
    return JSON.parse(extracted);
  } catch (error) {
    return { __parseError: error, __rawText: extracted };
  }
};

const extractCompleteSlideObjects = (text) => {
  const source = stripCodeFence(text);
  const slidesKey = source.search(/"slides"\s*:\s*\[/);
  if (slidesKey < 0) return [];
  const arrayStart = source.indexOf('[', slidesKey);
  const objects = [];
  let depth = 0;
  let start = -1;
  let inString = false;
  let escaped = false;
  for (let i = arrayStart + 1; i < source.length; i++) {
    const ch = source[i];
    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (ch === '\\') {
        escaped = true;
      } else if (ch === '"') {
        inString = false;
      }
      continue;
    }
    if (ch === '"') {
      inString = true;
      continue;
    }
    if (ch === '{') {
      if (depth === 0) start = i;
      depth++;
      continue;
    }
    if (ch === '}') {
      depth--;
      if (depth === 0 && start >= 0) {
        const objectText = source.slice(start, i + 1);
        try { objects.push(JSON.parse(objectText)); } catch (error) {}
        start = -1;
      }
    }
  }
  return objects;
};

const cleanAscii = (value) => String(value || '')
  .replace(/[^\x09\x0A\x0D\x20-\x7E]/g, '')
  .replace(/[ \t]+/g, ' ')
  .trim();

const titleFromStep = (step, fallbackIndex) => {
  const base = cleanAscii(step?.title || step?.objective || step?.activity || 'Lesson Activity');
  return base.split(/[.!?。！？]/)[0].split(/\s+/).slice(0, 6).join(' ') || 'Lesson Activity ' + fallbackIndex;
};

const purposeFromStep = (step) => {
  const base = cleanAscii(step?.objective || step?.activity || step?.flow || 'Practice the target English through a clear activity.');
  return base.split(/[.!?。！？]/)[0].split(/\s+/).slice(0, 14).join(' ') || 'Practice the target English through a clear activity.';
};

const buildFallbackPlan = (existingSlides, candidateTitle) => {
  const output = [];
  const usedSteps = new Set();
  const addSlide = (slide) => {
    if (output.length >= prepared.totalSlides) return;
    const index = output.length;
    const isCover = index === 0;
    const rawStepId = isCover ? 'cover-step' : String(slide?.stepId || '');
    const step = stepMap.get(rawStepId);
    if (!isCover && !step) return;
    if (!isCover) usedSteps.add(rawStepId);
    output.push({
      id: 'slide-' + (index + 1),
      phaseKey: isCover ? 'cover' : step.phaseKey,
      stepId: isCover ? 'cover-step' : rawStepId,
      type: isCover ? 'cover' : cleanAscii(slide?.type || 'lesson'),
      title: cleanAscii(slide?.title || (isCover ? (candidateTitle || prepared.courseTitle) : titleFromStep(step, index + 1))),
      purpose: cleanAscii(slide?.purpose || (isCover ? 'Introduce the English learning adventure.' : purposeFromStep(step)))
    });
  };

  const sortedExisting = [...existingSlides]
    .filter((slide) => slide && typeof slide === 'object')
    .sort((a, b) => {
      const ai = Number(String(a.id || '').match(/slide-(\d+)/i)?.[1]) || 999;
      const bi = Number(String(b.id || '').match(/slide-(\d+)/i)?.[1]) || 999;
      return ai - bi;
    });
  sortedExisting.forEach(addSlide);
  if (!output.length) addSlide({ title: candidateTitle || prepared.courseTitle, purpose: 'Introduce the English learning adventure.' });
  const missingStepIds = stepIds.filter((stepId) => !usedSteps.has(stepId));
  for (const stepId of missingStepIds) {
    addSlide({ stepId });
  }
  const fillStepIds = missingStepIds.length ? missingStepIds : stepIds;
  let cursor = 0;
  while (output.length < prepared.totalSlides && fillStepIds.length) {
    const stepId = fillStepIds[cursor % fillStepIds.length];
    const step = stepMap.get(stepId);
    addSlide({ stepId, title: titleFromStep(step, output.length + 1), purpose: purposeFromStep(step) });
    cursor++;
  }
  return output;
};

let candidate = raw.output ?? raw.text ?? raw;
let parsed = parseJsonLike(candidate);
let candidateTitle = cleanAscii(parsed?.title || prepared.courseTitle);
let slides = parsed.slides || parsed.presentation?.slides;
if (!Array.isArray(slides)) {
  const recoveredSlides = typeof candidate === 'string' ? extractCompleteSlideObjects(candidate) : [];
  if (!recoveredSlides.length) {
    const reason = parsed.__parseError?.message ? ': ' + parsed.__parseError.message : '';
    throw new Error('Slide planner returned no parseable slides' + reason);
  }
  slides = buildFallbackPlan(recoveredSlides, candidateTitle);
} else if (slides.length !== prepared.totalSlides) {
  slides = buildFallbackPlan(slides, candidateTitle);
}

if (slides.length !== prepared.totalSlides) throw new Error('Slide planner expected ' + prepared.totalSlides + ' slides but recovered ' + slides.length);
const covered = new Set();
const normalized = slides.map((slide, index) => {
  const isCover = index === 0;
  const stepId = isCover ? 'cover-step' : String(slide.stepId || '');
  if (!isCover && !stepMap.has(stepId)) throw new Error('Slide plan contains unknown step ID: ' + stepId);
  const phaseKey = isCover ? 'cover' : stepMap.get(stepId).phaseKey;
  const title = cleanAscii(slide.title || '').trim();
  const purpose = cleanAscii(slide.purpose || '').trim();
  if (!title || !purpose) throw new Error('Slide plan item ' + (index + 1) + ' is incomplete');
  if (cjk.test(title) || cjk.test(purpose)) throw new Error('Slide plan item ' + (index + 1) + ' is not English');
  if (!isCover) covered.add(stepId);
  return { id: 'slide-' + (index + 1), phaseKey, stepId, type: isCover ? 'cover' : String(slide.type || 'content'), title, purpose };
});
const missing = stepIds.filter((id) => !covered.has(id));
if (missing.length) throw new Error('Slide plan misses lesson steps: ' + missing.join(', '));
return normalized.map((slide, slideIndex) => ({ json: {
  slidePlan: slide,
  slideIndex,
  totalSlides: prepared.totalSlides,
  presentationTitle: candidateTitle,
  sourceStep: slide.stepId === 'cover-step' ? null : stepMap.get(slide.stepId),
  courseTitle: prepared.courseTitle,
  courseContext: prepared.courseContext,
  visualStyle: prepared.visualStyle,
  templateId: prepared.templateId
} }));

const raw = $json || {};

const stripCodeFence = (value) => String(value || '')
  .trim()
  .replace(/^\`\`\`(?:json)?\s*/i, '')
  .replace(/\`\`\`$/i, '')
  .trim();

const extractJsonObject = (value) => {
  const text = stripCodeFence(value);
  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  return first >= 0 && last > first ? text.slice(first, last + 1) : text;
};

const escapeLooseQuotes = (value) => {
  let output = '';
  let inString = false;
  let escaped = false;
  for (let i = 0; i < value.length; i++) {
    const ch = value[i];
    if (!inString) {
      if (ch === '"') inString = true;
      output += ch;
      continue;
    }
    if (escaped) {
      output += ch;
      escaped = false;
      continue;
    }
    if (ch === '\\') {
      output += ch;
      escaped = true;
      continue;
    }
    if (ch === '"') {
      const rest = value.slice(i + 1);
      const next = rest.match(/\S/)?.[0] || '';
      let closesString = !next || [':', '}', ']'].includes(next);
      if (next === ',') {
        const afterComma = rest.slice(rest.indexOf(',') + 1).trimStart();
        closesString = /^"(?:[^"\\]|\\.)*"\s*:/.test(afterComma);
      }
      if (closesString) {
        output += ch;
        inString = false;
      } else {
        output += '\\"';
      }
      continue;
    }
    output += ch;
  }
  return output;
};

const parseJsonLike = (value) => {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  const extracted = extractJsonObject(value);
  if (!extracted) throw new Error('The slide model returned an empty response');
  const attempts = [extracted, escapeLooseQuotes(extracted)];
  let lastError;
  for (const attempt of attempts) {
    try {
      return JSON.parse(attempt);
    } catch (error) {
      lastError = error;
    }
  }
  const preview = extracted.slice(0, 500).replace(/\s+/g, ' ');
  throw new Error(`Invalid slide JSON from model: ${lastError.message}. Preview: ${preview}`);
};

const sanitizeText = (value) => String(value ?? '')
  .replace(/[^\x09\x0A\x0D\x20-\x7E]/g, '')
  .replace(/[ \t]+/g, ' ')
  .replace(/ *\n */g, '\n')
  .trim();

const sanitizeDeep = (value) => {
  if (typeof value === 'string') return sanitizeText(value);
  if (Array.isArray(value)) return value.map(sanitizeDeep);
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, child]) => [key, sanitizeDeep(child)]));
  }
  return value;
};

const responseCandidate = (value) => {
  const candidate = value.output
    ?? value.text
    ?? value.content
    ?? value.response
    ?? value.message?.content
    ?? value.choices?.[0]?.message?.content
    ?? value;
  if (Array.isArray(candidate)) {
    return candidate
      .map((part) => typeof part === 'string' ? part : (part?.text ?? part?.content ?? ''))
      .join('');
  }
  return candidate;
};

const contexts = $('Parse Slide Plan').all().map((item) => item.json);
const currentIndex = typeof $itemIndex === 'number' ? $itemIndex : 0;
let context = contexts[currentIndex];

const buildFallbackSlide = (slideContext, reason) => {
  if (!slideContext) throw new Error(`No slide-plan context found for item ${currentIndex + 1}`);
  const plan = slideContext.slidePlan || {};
  const isCover = slideContext.slideIndex === 0;
  const id = String(plan.id || `slide-${slideContext.slideIndex + 1}`);
  const title = sanitizeText(plan.title) || (isCover ? 'English Learning Adventure' : 'English Practice');
  const purpose = sanitizeText(plan.purpose) || (isCover
    ? 'A playful journey to learn English together.'
    : 'Learn, speak, and practice English together.');
  const elements = isCover ? [
    { id: `${id}-title`, type: 'text', role: 'title', content: title, x: 90, y: 145, width: 760, height: 90, fontSize: 48, fontWeight: 'bold', color: '#253142', textAlign: 'center' },
    { id: `${id}-subtitle`, type: 'text', role: 'subtitle', content: purpose, x: 150, y: 255, width: 640, height: 60, fontSize: 24, fontWeight: 'normal', color: '#385A7C', textAlign: 'center' }
  ] : [
    { id: `${id}-eyebrow`, type: 'text', role: 'eyebrow', content: 'ENGLISH LEARNING', x: 64, y: 58, width: 300, height: 36, fontSize: 18, fontWeight: 'bold', color: '#3978A8', textAlign: 'left' },
    { id: `${id}-title`, type: 'text', role: 'title', content: title, x: 64, y: 108, width: 720, height: 80, fontSize: 42, fontWeight: 'bold', color: '#253142', textAlign: 'left' },
    { id: `${id}-body`, type: 'text', role: 'body', content: purpose, x: 64, y: 220, width: 620, height: 100, fontSize: 24, fontWeight: 'normal', color: '#385A7C', textAlign: 'left' }
  ];
  return {
    id,
    phaseKey: String(plan.phaseKey || (isCover ? 'cover' : '')),
    stepId: String(plan.stepId || (isCover ? 'cover-step' : '')),
    type: String(plan.type || (isCover ? 'cover' : 'content')),
    title,
    speakerNotes: isCover
      ? 'Welcome learners and introduce the English learning adventure.'
      : `Guide learners through this activity: ${purpose}`,
    visualPrompt: `${sanitizeText(slideContext.visualStyle)} Text-free child-friendly educational illustration with generous negative space.`.trim(),
    layout: { name: isCover ? 'cover' : 'title-focus', background: '#FFFFFF', elements },
    generationWarning: sanitizeText(reason)
  };
};

let slide;
try {
  const parsed = sanitizeDeep(parseJsonLike(responseCandidate(raw)));
  const parsedSlide = parsed.slide || parsed;
  const parsedId = String(parsedSlide?.id || '');
  const parsedIndex = Number(parsedId.match(/slide-(\d+)/i)?.[1]) - 1;
  if (!context && parsedId) context = contexts.find((item) => item.slidePlan?.id === parsedId);
  if (!context && Number.isInteger(parsedIndex)) context = contexts[parsedIndex];
  if (!context) throw new Error(`No slide-plan context found for ${parsedId || `item ${currentIndex + 1}`}`);
  if (!parsedSlide?.layout || !Array.isArray(parsedSlide.layout.elements) || parsedSlide.layout.elements.length < 2) {
    throw new Error(`No usable layout returned for ${context.slidePlan.id}`);
  }
  slide = parsedSlide;
} catch (error) {
  slide = buildFallbackSlide(context, error.message);
}

// The slide plan is authoritative; prevent a model hallucination from shifting item identity.
slide.id = context.slidePlan.id;
slide.phaseKey = context.slidePlan.phaseKey;
slide.stepId = context.slidePlan.stepId;
slide.type = context.slidePlan.type;
slide.title = sanitizeText(slide.title) || sanitizeText(context.slidePlan.title);

return { json: {
  slideIndex: context.slideIndex,
  presentationTitle: context.presentationTitle,
  templateId: context.templateId,
  slide
} };

const items = $input.all().map((item) => item.json).sort((a, b) => a.slideIndex - b.slideIndex);
if (!items.length) throw new Error('No generated slides reached aggregation');
const prepared = $('Prepare Course Context').first().json;
if (items.length !== prepared.totalSlides) throw new Error(`Expected ${prepared.totalSlides} generated slides but received ${items.length}`);
const cjk = /[\u3400-\u4dbf\u4e00-\u9fff\uf900-\ufaff]/;
const findCjk = (value, path = 'presentation') => {
  if (typeof value === 'string' && cjk.test(value)) return path;
  if (Array.isArray(value)) {
    for (let i = 0; i < value.length; i++) { const found = findCjk(value[i], `${path}[${i}]`); if (found) return found; }
  } else if (value && typeof value === 'object') {
    for (const [key, child] of Object.entries(value)) { const found = findCjk(child, `${path}.${key}`); if (found) return found; }
  }
  return null;
};
const clamp = (value, min, max, fallback) => Math.min(max, Math.max(min, Number(value) || fallback));
const allowedAlign = new Set(['left', 'center', 'right']);
const allowedWeight = new Set(['normal', 'bold']);
const phases = JSON.parse(prepared.lessonPlan);
const stepIds = new Set(phases.flatMap((phase) => phase.steps.map((step) => step.id)));
const normalizedSlides = items.map((item, slideIndex) => {
  const input = item.slide || {};
  const isCover = slideIndex === 0;
  const phaseKey = isCover ? 'cover' : String(input.phaseKey || '');
  const stepId = isCover ? 'cover-step' : String(input.stepId || '');
  if (!isCover && !stepIds.has(stepId)) throw new Error(`Unknown lesson step ID on slide ${slideIndex + 1}: ${stepId}`);
  const elements = input.layout.elements.map((element, elementIndex) => {
    const x = clamp(element.x, 48, 892, 64);
    const y = clamp(element.y, 48, 481, 64);
    const width = clamp(element.width, 48, 940 - x, 400);
    const height = clamp(element.height, 28, 529 - y, 60);
    const content = String(element.content || '').trim();
    if (!content) throw new Error(`Empty text element on slide ${slideIndex + 1}`);
    return {
      id: String(element.id || `slide-${slideIndex + 1}-element-${elementIndex + 1}`),
      type: 'text', role: String(element.role || 'body'), content,
      x, y, width, height,
      fontSize: clamp(element.fontSize, 18, 64, element.role === 'title' ? 38 : 22),
      fontWeight: allowedWeight.has(element.fontWeight) ? element.fontWeight : 'normal',
      color: /^#[0-9a-f]{6}$/i.test(element.color || '') ? element.color : '#253142',
      textAlign: allowedAlign.has(element.textAlign) ? element.textAlign : 'left'
    };
  });
  if (elements.length < 2 || elements.length > 5) throw new Error(`Slide ${slideIndex + 1} must contain 2 to 5 text elements`);
  return {
    id: `slide-${slideIndex + 1}`,
    phaseKey, stepId,
    type: isCover ? 'cover' : String(input.type || 'content'),
    title: String(input.title || elements.find((element) => element.role === 'title')?.content || `Slide ${slideIndex + 1}`),
    speakerNotes: String(input.speakerNotes || ''),
    visualPrompt: String(input.visualPrompt || 'Text-free child-friendly educational illustration with generous negative space.'),
    layout: {
      name: String(input.layout.name || (isCover ? 'cover' : 'title-focus')),
      background: /^#[0-9a-f]{6}$/i.test(input.layout.background || '') ? input.layout.background : '#FFFFFF',
      elements
    }
  };
});
const chinesePath = findCjk(normalizedSlides);
if (chinesePath) throw new Error(`Non-English content detected at ${chinesePath}`);
const coveredSteps = new Set(normalizedSlides.filter((slide) => slide.phaseKey !== 'cover').map((slide) => slide.stepId));
const missingSteps = [...stepIds].filter((id) => !coveredSteps.has(id));
if (missingSteps.length) throw new Error(`Slides missing for lesson steps: ${missingSteps.join(', ')}`);
return [{ json: { success: true, presentation: {
  title: String(items[0].presentationTitle || prepared.courseTitle),
  language: 'English',
  slideSize: { width: 940, height: 529 },
  templateId: prepared.templateId,
  slides: normalizedSlides
} } }];
